import{_ as t,o as i,c as n,ae as o}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"📑 Software Requirements Specification (SRS) - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"SRS.md","filePath":"SRS.md"}'),r={name:"SRS.md"};function a(s,e,l,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="📑-software-requirements-specification-srs-tendercheck-ai" tabindex="-1">📑 Software Requirements Specification (SRS) - TenderCheck AI <a class="header-anchor" href="#📑-software-requirements-specification-srs-tendercheck-ai" aria-label="Permalink to &quot;📑 Software Requirements Specification (SRS) - TenderCheck AI&quot;">​</a></h1><h2 id="_1-project-overview" tabindex="-1">1. Project Overview <a class="header-anchor" href="#_1-project-overview" aria-label="Permalink to &quot;1. Project Overview&quot;">​</a></h2><p><strong>TenderCheck AI</strong> is an intelligent assistant designed to automate the formal validation of public tender documents. It compares a &quot;Pliego de Condiciones&quot; (Tender Requirements) against a &quot;Propuesta Técnica&quot; (Technical Offer) using a hybrid approach of deterministic rules and LLM-based semantic reasoning.</p><h2 id="_2-professional-academic-standards-mandatory" tabindex="-1">2. Professional &amp; Academic Standards (MANDATORY) <a class="header-anchor" href="#_2-professional-academic-standards-mandatory" aria-label="Permalink to &quot;2. Professional &amp; Academic Standards (MANDATORY)&quot;">​</a></h2><p><em>Based on Master&#39;s Final Project Official Guidelines:</em></p><ul><li><strong>Architecture:</strong> Clean Architecture (Domain, Application, Infrastructure, Presentation).</li><li><strong>Quality Gate:</strong> Minimum <strong>71% core branch coverage (60% global)</strong> enforced via Vitest.</li><li><strong>Security:</strong> - Runtime validation using <strong>Zod</strong>. <ul><li>Security headers via <strong>Helmet.js</strong>.</li><li>Input sanitization (XSS prevention).</li></ul></li><li><strong>DevOps:</strong> GitHub Actions for CI/CD, Husky for pre-push hooks.</li><li><strong>AI Ethics:</strong> Every AI decision must include an <code>explanation</code> and <code>evidence</code> from the source text.</li></ul><h2 id="_3-functional-requirements-fr" tabindex="-1">3. Functional Requirements (FR) <a class="header-anchor" href="#_3-functional-requirements-fr" aria-label="Permalink to &quot;3. Functional Requirements (FR)&quot;">​</a></h2><ul><li><strong>FR-1: Document Ingestion:</strong> The system must accept a PDF file (Tender Documents).</li><li><strong>FR-2: Text Extraction:</strong> Convert PDF content into normalized text for processing.</li><li><strong>FR-3: Semantic Search &amp; RAG:</strong><ul><li>Use <strong>Google Genkit (<code>gemini-embedding-001</code>)</strong> to generate vector embeddings (3072D).</li><li>Store and retrieve embeddings via <strong>Turso (LibSQL)</strong>.</li></ul></li><li><strong>FR-4: Requirement Extraction:</strong><ul><li><strong>Dual Persona Strategy</strong>: <ul><li><strong>&quot;Legal Auditor&quot;</strong>: Extracts strict mandatory requirements (&quot;deberá&quot;, &quot;obligatorio&quot;).</li><li><strong>&quot;Senior Evaluator&quot;</strong>: Validates semantic compliance of technical proposals.</li></ul></li></ul></li><li><strong>FR-5: Compliance Validation:</strong> Real-time checking of proposals against extracted requirements.</li><li><strong>FR-6: Status Attribution:</strong><ul><li><code>COMPLIANT</code> (Green)</li><li><code>NON_COMPLIANT</code> (Red)</li><li><code>PARTIALLY_MET</code> (Amber) - <em>Implemented</em></li></ul></li><li><strong>FR-7: Report Generation:</strong> Produce a final validation report and a dashboard with <strong>AI Reliability Score</strong>.</li></ul><h2 id="_4-non-functional-requirements-nfr" tabindex="-1">4. Non-Functional Requirements (NFR) <a class="header-anchor" href="#_4-non-functional-requirements-nfr" aria-label="Permalink to &quot;4. Non-Functional Requirements (NFR)&quot;">​</a></h2><ul><li><strong>NFR-1: Transparency:</strong> The system must specify if a result was obtained via <code>RULE</code> or <code>AI</code>.</li><li><strong>NFR-2: Performance:</strong><ul><li><strong>Context Window</strong>: Support up to <strong>1M tokens</strong> via Gemini 2.5 Flash.</li><li><strong>Response Time</strong>: &lt;60 seconds for full tender analysis (Render Free Tier constraints).</li></ul></li><li><strong>NFR-3: Reliability:</strong> The system must handle PDF parsing errors gracefully.</li><li><strong>NFR-4: Observability:</strong> Integrated <strong>Sentry</strong> for error tracking.</li></ul><h2 id="_5-technical-stack" tabindex="-1">5. Technical Stack <a class="header-anchor" href="#_5-technical-stack" aria-label="Permalink to &quot;5. Technical Stack&quot;">​</a></h2><ul><li><strong>Runtime:</strong> Node.js (LTS 22+)</li><li><strong>Language:</strong> TypeScript (Strict Mode)</li><li><strong>AI Framework:</strong> <strong>Google Genkit</strong> (Gemini 2.5 Flash + gemini-embedding-001)</li><li><strong>Database:</strong> <strong>Turso</strong> (Distributed SQLite)</li><li><strong>Frontend:</strong> React + Vite + TailwindCSS</li><li><strong>Deployment:</strong> <strong>Render</strong> (Cloud Native)</li><li><strong>Testing:</strong> Vitest</li><li><strong>Validation:</strong> Zod</li><li><strong>API Security:</strong> Helmet, Rate Limiting, CORS</li></ul><h2 id="_6-project-constraints-scope" tabindex="-1">6. Project Constraints &amp; Scope <a class="header-anchor" href="#_6-project-constraints-scope" aria-label="Permalink to &quot;6. Project Constraints &amp; Scope&quot;">​</a></h2><ul><li><strong>Domain:</strong> Limited to IT/Software services tenders.</li><li><strong>Out of Scope:</strong> Economic evaluation, automated legal binding decisions, and OCR for handwritten documents.</li></ul>',14)])])}const h=t(r,[["render",a]]);export{m as __pageData,h as default};
